// The sample dossier behind /d/sample (spec D1, plan S0b). Sample data.
//
// Curated by hand from the Parallel spike results already paid for (scripts/spike/out:
// task-ultra.json, task-ultra-enriched-core.json, findall-gov-enriched-core.json; run date
// 2026-10-30). No new research. Real organisations only; the client is an unnamed sample.
//
// Rules this file follows (checked by sample-dossier.test.ts):
// - Every source keeps Parallel's URL exactly (S3 mock mode matches ratings by URL, plan P-1)
//   and a verbatim Basis excerpt. Citations that fail spec §7.4 are kept with accepted=false
//   and a rejectReason, and are never cited.
// - Every rating, statement, title, next step, edge and brief sentence cites accepted
//   sources; every quote appears in the cited excerpt. No source → Unverified; no statement
//   → support Unknown.
// - Names only for sourced public officials (spec §16 Q6); nobody else is named.
// - No Chinese organisations, so nothing here is a person row.
import { SAMPLE_DOSSIER_ID, SAMPLE_SHARE_ID } from "@/lib/ids";
import { briefMetrics } from "@/lib/scoring";
import type {
  Brief,
  BriefingNoteContent,
  Category,
  Contact,
  Credibility,
  Dossier,
  DocumentRequest,
  Edge,
  Fact,
  IntroDraft,
  FactField,
  Lead,
  MatchCheck,
  NoteSection,
  PortolanDocument,
  Rating03,
  Reliability,
  Sentence,
  Source,
  SourceType,
  Stakeholder,
  StatementRating,
  SupportStatement,
  TeamMember,
  Tie,
  TimedEvent,
  TrackerItem,
} from "@/lib/types";

const D = SAMPLE_DOSSIER_ID;
const RUN_ID = "sample-run";
/** When the spike ran; every record is dated from it. */
const AT = "2026-10-30T04:09:36Z";
/** "Today" for the brief's metric snapshot. */
const SNAPSHOT_AT = new Date("2026-11-01T00:00:00Z");
export const NO_ROUTE = "Find a sourced contact route first";

// ─── Sources ─────────────────────────────────────────────────────────────────

interface RawSource {
  key: string;
  url: string;
  title: string;
  publisher: string | null;
  sourceType: SourceType;
  excerptLang: string;
  reliability: Reliability;
  credibility: Credibility;
  credibilityReason: string;
  verifiedAt: string;
  accepted: boolean;
  rejectReason: string | null;
  excerpt: string;
}

const RAW = rawSources();

/** Short handle → source, e.g. "upmedia-263412". Handles are only used inside this file. */
export const sourceKeys = new Map<string, string>();

const sources: Source[] = RAW.map((r, i) => {
  const id = `s${i + 1}`;
  sourceKeys.set(r.key, id);
  return {
    id,
    dossierId: D,
    label: `S${i + 1}`,
    url: r.url,
    title: r.title,
    publisher: r.publisher,
    sourceType: r.sourceType,
    excerpt: r.excerpt,
    excerptLang: r.excerptLang,
    translation: null,
    reliability: r.reliability,
    credibility: r.credibility,
    credibilityReason: r.credibilityReason,
    publishedAt: null,
    verifiedAt: r.verifiedAt,
    origin: "parallel_basis",
    accepted: r.accepted,
    rejectReason: r.rejectReason,
    runId: RUN_ID,
    createdAt: AT,
  };
});

/** Source id for a handle; a typo fails at import, so the test catches it. */
function sid(key: string): string {
  const id = sourceKeys.get(key);
  if (!id) throw new Error(`sample-dossier: unknown source handle "${key}"`);
  return id;
}

// ─── Stakeholders (hand-curated) ─────────────────────────────────────────────

/** [source handle, text in its excerpt that the claim relies on] */
type Cite = [key: string, quote: string];
type Rated = [rating: Rating03, value: string, ...cite: Cite];
type Said = [rating: StatementRating, summary: string, ...cite: Cite];
type Told = [value: string, ...cite: Cite];

interface Org {
  id: string;
  name: string;
  nameZh: string | null;
  short: string;
  category: Category;
  city?: string;
  pos: [number, number, number];
  role: Told;
  /** Sourced public officials only (Q6). */
  head?: Told;
  authority?: Rated;
  budget?: Rated;
  access?: Rated;
  recent?: Rated;
  said?: Said[];
  /** Null → "Find a sourced contact route first" (Unverified). */
  action: Told | null;
}

