const check = (label: string, ...keys: string[]): MatchCheck => ({ label, passed: keys.length > 0, sourceIds: keys.map(sid) });
const level = (checks: MatchCheck[]) => {
  const n = checks.filter((c) => c.passed).length;
  return n === 4 ? "High" : n >= 2 ? "Medium" : "Low";
};

const s = (text: string, ...keys: string[]): Sentence => ({ text, sourceIds: keys.map(sid) });

function lead(
  type: Lead["type"],
  stakeholderId: string,
  kind: string,
  checks: MatchCheck[] | null,
  why: Sentence,
  route: string | null,
  eventDate: string | null = null,
): Lead {
  const o = ORGS.find((x) => x.id === stakeholderId)!;
  return {
    id: `lead-${stakeholderId}`,
    dossierId: D,
    type,
    stakeholderId,
    name: o.name,
    kind,
    match: checks ? { type: "checks", checks, level: level(checks) } : { type: "attendees", stakeholderIds: [] },
    meta: null,
    why,
    route,
    eventDate,
    sourceIds: why.sourceIds,
    verification: "sourced",
    status: "new",
    createdAt: AT,
  };
}

